      "passage_id": "SOR-2026-08-P198-S209",
      "quote": "The athlete is not allowed to compete while bleeding.",
      "supports": "El atleta no tiene permitido competir mientras esté sangrando."
    },
    {
      "passage_id": "SOR-2026-08-P198-S209",
      "quote": "The athlete may continue competing only once the bleeding is fully controlled and isolated.",
      "supports": "El atleta puede continuar compitiendo únicamente una vez que el sangrado esté completamente controlado y aislado."
    },
    {
      "passage_id": "SOR-2026-08-P198-S209",
      "quote": "The athlete is allowed to receive medical treatment for bleeding, on two (2) occasions only.",
      "supports": "El atleta tiene permitido recibir tratamiento médico para el sangrado en dos ocasiones únicamente."
    }
  ],
